/// Encode a value in unsigned LEB128, 7 bits per byte from the least significant, MSb set when more bytes follow
fn var_uint_encode(mut value: u64, data: &mut Vec<u8>) {
    while value >= 0x80 {
        data.push((value as u8) | 0x80);
        value >>= 7;
    }
    data.push(value as u8);
}

/// Decode an unsigned LEB128 value
///
/// Returns the value and its size in bytes, None if it is cut short, over 10 bytes or over max_value
fn var_uint_decode(data: &[u8], max_value: u64) -> Option<(u64, usize)> {
    let mut value: u64 = 0;
    // A u64 takes up to 10 bytes, the 10th holds bit 63 only
    for (idx, &byte) in data.iter().take(10).enumerate() {
        let group = u64::from(byte & 0x7F);
        if idx == 9 && group > 1 {
            return None;
        }
        value |= group << (7 * idx);
        if byte & 0x80 == 0 {
            return (value <= max_value).then_some((value, idx + 1));
        }
    }
    None
}

/// Map a signed value to unsigned so small magnitudes stay small: 0, -1, 1, -2 give 0, 1, 2, 3
fn zigzag_encode(value: i64) -> u64 {
    ((value << 1) ^ (value >> 63)) as u64
}

/// Map a zigzag value back to signed
fn zigzag_decode(value: u64) -> i64 {
    ((value >> 1) as i64) ^ -((value & 1) as i64)
}

